  featureHub: "A curated, offline-first catalog plus optional live Hugging Face search.",
  featureDashboard: "A React and TypeScript UI with training, introspection, analysis, targets, energy, hub, and pipeline panels, plus seven guided walkthroughs.",
  dashboardAlt: "The Spikeforge Model and Data dashboard with dataset, encoding, topology, and live training controls.",
  dashboardCaption: "The bundled dashboard, running locally with <code>docker compose up --build</code>.",
  statusNir: "NIR export & validation", statusNirNote: "An independent reference interpreter checks numerical drift against tolerances.",
  statusDeterminism: "Determinism & run tracking", statusDeterminismNote: "Seeded, checked for bit-exactness, and recorded in a manifest for every run.",
  statusServeNote: "Predict, stream, and metrics endpoints with versioned deployment bundles and standalone install, run, list, and uninstall commands.",
